export const STATE_REGION = {
  AN: 'South & East India', AP: 'South & East India', AR: 'South & East India',
  AS: 'South & East India', BR: 'South & East India', CH: 'North & West India',
  CT: 'Unclassified leads', DH: 'North & West India', DL: 'North & West India',
  GA: 'North & West India', GJ: 'North & West India', HR: 'North & West India',
  HP: 'North & West India', JK: 'North & West India', JH: 'South & East India',
  KA: 'South & East India', KL: 'South & East India', LA: 'North & West India',
  LD: 'South & East India', MP: 'Unclassified leads', MH: 'North & West India',
  MN: 'South & East India', ML: 'South & East India', MZ: 'South & East India',
  NL: 'South & East India', OR: 'South & East India', PY: 'South & East India',
  PB: 'North & West India', RJ: 'North & West India', SK: 'South & East India',
  TN: 'South & East India', TG: 'South & East India', TR: 'South & East India',
  UP: 'North & West India', UT: 'North & West India', WB: 'South & East India',
}

export const INDIA_LOCATIONS = CITIES.map(([city, stateCode]) => ({
  city, state: STATES[stateCode] || stateCode, stateCode,
  region: STATE_REGION[stateCode] || 'Unclassified leads',
  value: city + ' — ' + (STATES[stateCode] || stateCode),
})).sort((a, b) => a.state.localeCompare(b.state) || a.city.localeCompare(b.city))

export const INDIA_LOCATION_GROUPS = [...new Set(INDIA_LOCATIONS.map(item => item.state))]
  .sort((a, b) => a.localeCompare(b))
  .map(state => ({ state, locations: INDIA_LOCATIONS.filter(item => item.state === state) }))

const byValue = new Map(INDIA_LOCATIONS.map(item => [item.value, item]))
const byCity = new Map()
for (const item of INDIA_LOCATIONS) {
  if (!byCity.has(item.city.toLowerCase())) byCity.set(item.city.toLowerCase(), item)
}

const searchableLocationText = value => String(value || '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim()
  .replace(/\s+/g, ' ')

const embeddedLocation = value => {
  const text = searchableLocationText(value)
  if (!text) return null
  const padded = ` ${text} `
  // Prefer the longest city name so "New Delhi" wins over the shorter
  // "Delhi" when both appear in an address.
  return [...byCity.values()]
    .sort((left, right) => searchableLocationText(right.city).length - searchableLocationText(left.city).length)
    .find(item => {
      const city = searchableLocationText(item.city)
      return city && padded.includes(` ${city} `)
    }) || null
}

export function indiaLocation(value) {
  const text = String(value || '').trim()
  return byValue.get(text) || byCity.get(text.toLowerCase()) || null
}

export function regionForState(stateCode, config) {
  const rows = config?.stateRegions
  if (Array.isArray(rows)) {
    const hit = rows.find(r => r.code === stateCode)
    if (hit) return hit.region
  }
  return STATE_REGION[stateCode] || 'Unclassified leads'
}

export function indiaRegionForLocation(value, config) {
  const text = String(value || '').trim()
  const loc = indiaLocation(value) || embeddedLocation(value)
  if (loc) return regionForState(loc.stateCode, config)
  const normalized = searchableLocationText(text)
  const state = Object.entries(STATES).find(([code, name]) =>
    normalized === searchableLocationText(code)
      || normalized === searchableLocationText(name)
      || ` ${normalized} `.includes(` ${searchableLocationText(name)} `))
  return state ? regionForState(state[0], config) : ''
}
